const systemPrompt = `Eres AsistenteAgro, un asistente de inteligencia artificial especializado en agricultura de Colombia.

CONTEXTO:
- País: Colombia
- Plataforma: SembraData - Predicción agroclimática nacional
- Cultivos principales: Cacao, Café, Granadilla

CONOCIMIENTO POR CULTIVO:
- Cacao: Rendimiento 0.85-2.5 Ton/Ha, siembra abr-may, temp 20-28°C, humedad 70-90%, suelo pH 5.0-7.0
- Café: Rendimiento 1.2-2.5 Ton/Ha, siembra mar-abr, altitud 1200-1800 msnm, temp 17-24°C
- Granadilla: Rendimiento 9.5-15 Ton/Ha, siembra sep-oct, temp 18-24°C, humedad 60-80%

CLIMA DE COLOMBIA:
- Región Caribe: Tropical seco, temp 24-35°C
- Región Andina: Tropical de montaña, temp 12-24°C
- Región Pacífica: Tropical húmedo, lluvias 3000-8000 mm/año
- Región Orinoquía: Sabana tropical, temp 24-28°C
- Región Amazonía: Ecuatorial, temp 22-28°C

INSTRUCCIONES:
- Responde en español, conciso y práctico
- Usa markdown
- Máximo 3-4 párrafos
- Relaciona la respuesta con Colombia y el contexto del municipio/cultivo`;

const input = $input.first().json;
const ctx = input.context || {};
const kb = input.knowledgeContext?.entries || [];

let ragSection = '';
if (kb.length > 0) {
  ragSection = '\n\nINFORMACIÓN RELEVANTE DE LA BASE DE CONOCIMIENTO:\n' + kb.map((e, i) => `${i + 1}. ${e.question}\n   ${e.answer}`).join('\n');
}

const userContext = `Pregunta del usuario: ${input.message}

Contexto adicional:
- Municipio: ${ctx.municipio || 'No especificado'}
- Departamento: ${ctx.departamento || 'No especificado'}
- Cultivo seleccionado: ${ctx.cultivo || 'No especificado'}
- Nivel de riesgo actual: ${ctx.riesgo || 'No disponible'}`;

const model = $env.MODEL_NAME || 'gpt-4o-mini';

return [{
  json: {
    body: {
      model: model,
      messages: [
        { role: 'system', content: systemPrompt + ragSection },
        { role: 'user', content: userContext }
      ],
      max_tokens: 600,
      temperature: 0.7
    }
  }
}];

// Soporta OpenAI (choices[].message.content), Ollama (message.content), y otros formatos
const body = $input.first().json;
const content = body.choices?.[0]?.message?.content
  || body.message?.content
  || body.reply
  || body.response
  || 'No pude generar una respuesta.';

return [{
  json: {
    reply: content,
    source: 'n8n',
    confidence: 0.85,
    metadata: {
      variablesUsadas: ['temperatura', 'precipitación', 'humedad', 'tipo de cultivo', 'altitud'],
      fuentes: ['Open-Meteo', 'NASA POWER', 'SoilGrids', 'Base de conocimiento SembraData'],
      fechaActualizacion: new Date().toISOString().slice(0, 10)
    }
  }
}];

return [{
  json: {
    reply: 'Lo siento, no pude procesar tu consulta. El servicio de IA no está disponible en este momento. Por favor intenta de nuevo más tarde.',
    source: 'fallback',
    confidence: 0.1,
    metadata: {
      fuentes: [],
      fechaActualizacion: new Date().toISOString().slice(0, 10)
    }
  }
}];
